using System;using System.Linq;using System.Collections.Generic;using System.Threading.Tasks;using System.Windows.Controls;
namespace TriReviewBridge {
 public partial class WorkbenchApp {
  object DesktopRelayProof;
  bool IsDesktopRelay(object p){return Json.Str(p,"id")=="deepseek"&&Json.Str(p,"mode")=="CODEX_DESKTOP_RELAY";}
  bool HasDesktopRelay(){return Json.Arr(Json.Get(State,"participants")).Any(IsDesktopRelay);}
  bool HybridIdentityReported(object p){return Json.Str(p,"verificationLevel")=="WORKER_REPORTED_IDENTITY_MATCH"||IsDesktopRelay(p)&&Json.Str(p,"verificationLevel")=="USER_BOUND_WINDOW_TITLE_AND_ORIGINAL_ANCHOR";}
  string DesktopRelayParticipantLabel(object p){return "Codex电脑接力 · 依赖桌面空闲 · "+(Json.Bool(p,"paused")?"已暂停投递":Json.Bool(p,"dispatchAvailable")?"后端允许派发":"等待桌面核对")+" · "+(Json.Bool(p,"queueAvailable")?"可排队":"不可排队");}
  string DesktopObservation(object control,string key,string yes,string no){var value=Json.Get(control,key);return value==null?"未观察":Convert.ToBoolean(value)?yes:no;}
  string DesktopRelayDetails(object p){var c=Json.Get(p,"roleControl");return (HybridIdentityReported(p)?"用户绑定的窗口标题/原会话锚已核对。":"指定原窗口标题/原会话锚待核对。")+"\n原生Session UUID未观测；sessionId仅为期望引用。"+"\n桌面忙碌："+DesktopObservation(c,"busy","是，保留排队","本次观察未见")+"\n草稿："+DesktopObservation(c,"draftPresent","存在，保留排队","本次观察未见")+"\n用户输入："+DesktopObservation(c,"userInputDetected","已检测，保留排队","本次观察未见")+"\n电脑空闲时由当前Codex任务接力，可能切换指定原窗口。桌面转述不等于原生认证或完整工具轨迹。";}
  string DesktopRelayPreparationText(object p){return Json.Bool(p,"preparationRequested")?"已排队准备请求，等待当前Codex任务观察原窗口。":"准备后由当前Codex任务观察原窗口。";}
  void RefreshDesktopRelayLabels(){if(!HybridMode)return;foreach(ListBoxItem item in C<ListBox>("HybridRoleSelect").Items)item.Content=HybridRoleName(Convert.ToString(item.Tag));}
  void AppendDesktopRelayContext(List<string> issues,object p){issues.Add("DSH为Codex电脑接力，依赖桌面空闲；原生UUID未观测");var c=Json.Get(p,"roleControl");if(Json.Bool(c,"busy")||Json.Bool(c,"draftPresent")||Json.Bool(c,"userInputDetected"))issues.Add("DSH桌面暂不可安全投递，保留排队");else if(Json.Get(c,"busy")==null||Json.Get(c,"draftPresent")==null||Json.Get(c,"userInputDetected")==null)issues.Add("DSH桌面安全状态尚未完整观察");}
  async Task RunDesktopRelaySelfTest(){if(!HasDesktopRelay())throw new Exception("Desktop relay fixture missing");C<ListBox>("HybridRoleSelect").SelectedIndex=1;RefreshUxContext();var d=HybridSelectedParticipant();if(!HybridRoleName("deepseek").Contains("Codex电脑接力")||!HybridParticipantLabel(d).Contains("依赖桌面空闲")||!DesktopRelayDetails(d).Contains("未观察")||!DesktopRelayDetails(d).Contains("UUID未观测"))throw new Exception("Desktop relay truth missing");await HybridRoleAction("prepare");d=HybridSelectedParticipant();if(!Json.Bool(d,"preparationRequested")||!Json.Bool(d,"paused")||Json.Str(d,"verificationLevel")!="UNVERIFIED"||C<Button>("HybridEnableButton").IsEnabled)throw new Exception("Prepare became enable or identity observation");await RefreshWorkspace();d=HybridSelectedParticipant();if(!C<Button>("HybridEnableButton").IsEnabled||!HybridIdentityReported(d)||Json.Bool(d,"nativeSessionUuidObserved"))throw new Exception("Backend desktop enable gate was ignored");await HybridRoleAction("enable");if(Json.Bool(HybridSelectedParticipant(),"paused"))throw new Exception("Selected D enable did not execute");d=HybridSelectedParticipant();var c=Json.Obj(Json.Get(d,"roleControl"));foreach(string key in new[]{"busy","draftPresent","userInputDetected"}){object saved=c.ContainsKey(key)?c[key]:null;c[key]=true;RefreshUxContext();if(!C<TextBlock>("HybridRoleStatusText").Text.Contains("保留排队"))throw new Exception("Desktop unsafe observation hidden");c[key]=saved;}await HybridRoleAction("pause");if(!Json.Bool(HybridSelectedParticipant(),"paused"))throw new Exception("D pause did not persist");DesktopRelayProof=Json.D("passed",true,"mode","CODEX_DESKTOP_RELAY","label","Codex电脑接力·依赖桌面空闲","prepareRequestsObservationOnly",true,"enableUsesBackendGate",true,"busyDraftInputRemainQueued",true,"unknownSafetyNotFalse",true,"nativeSessionUuidObserved",false,"nativeRuntimeStarted",false,"originalSessionOperations",0);}
 }
}
